unsigned GpibEngine::RunOnce()
{
    if (SerialPoll == 0 || closed_)
        return kIdleMs;
    TSerialPoll* sp = SerialPoll;

#define GPIB_ENGINE_CLOSE_CHECK()      \
    if (sp->closeRequested)            \
    {                                  \
        DoClose();                     \
        return kIdleMs;                \
    }

    GPIB_ENGINE_CLOSE_CHECK();

    // serial chunks queued by the COM reader threads (CommAMD / CommAMD2 / fRS232Main->CommTester)
    sp->DrainRx();
    GPIB_ENGINE_CLOSE_CHECK();

    // golden TMyThread::Execute / Process (Unit2.cpp:31-37, 40-66): started by FormShow (bEnableThread)
    if (bEnableThread && InitialOK)
    {
        sp->ProcessAddress();
        //AI(W906-GB-PADSEEN) 20261007 (Jerry, J-19 "C"): say it out loud when the address on the CARD is not the
        //  address every screen shows.  golden sets the status bar in the Handler message handler and, in the same
        //  block, also assigns oldGpibAddress (Main.cpp:3315 / V12.13.883 -- the //wei 20150629 line), which makes
        //  ProcessAddress()'s `oldGpibAddress!=GpibAddress` guard false, so ibpad() never runs.  golden survives it
        //  because WriteLastDataFile() writes the new address into general.ini and the NEXT launch of the bridge exe
        //  boots correct; on this laptop that ini is read-only to the user, the write fails silently, and the card
        //  stayed on 10 while everything displayed 1 (measured 1007).  Nothing is corrected here on purpose -- that
        //  would be a deviation from golden, and is Jimmy's call.  This only removes the silence.
        //  Logged once per distinct pair, so a real mismatch does not drown lstRecord.
        if (bGpibMode)
        {
            const int onCard = LastPrimaryAddress();
            if (onCard >= 0 && onCard != LastSet.GpibAddress &&
                (onCard != padSaidCard_ || LastSet.GpibAddress != padSaidWanted_))
            {
                padSaidCard_ = onCard;
                padSaidWanted_ = LastSet.GpibAddress;
                AnsiString w;
                w.sprintf("!! ADDRESS MISMATCH: card is %d, display/recipe says %d -- the Tester calls %d and nobody answers"
                          " (ibpad never ran; see general.ini [SystemSetup] GpibAddress and docs/handoff J-19)",
                          onCard, LastSet.GpibAddress, LastSet.GpibAddress);
                sp->WriteLog(w.c_str());
            }
            else if (onCard >= 0 && onCard == LastSet.GpibAddress && padSaidCard_ >= 0)
            {
                padSaidCard_ = -1;   // agreed again: re-arm, so a later mismatch is reported afresh
                padSaidWanted_ = -1;
            }
        }
        GPIB_ENGINE_CLOSE_CHECK();
        sp->ProcessMessage();
        GPIB_ENGINE_CLOSE_CHECK();
    }

    // golden TTimer components (Main.dfm:1531 Timer1 300 ms, :1599 TimerTMode 10 ms; DummyArt.dfm:583)
    if (sp->Timer1 && Due(timer1_, sp->Timer1->Enabled, sp->Timer1->Interval, NowMs()))
    {
        sp->Timer1Timer(sp->Timer1);
        GPIB_ENGINE_CLOSE_CHECK();
    }
    if (sp->TimerTMode && Due(timerTMode_, sp->TimerTMode->Enabled, sp->TimerTMode->Interval, NowMs()))
    {
        sp->TimerTModeTimer(sp->TimerTMode);
        GPIB_ENGINE_CLOSE_CHECK();
    }
    if (fDummyART && fDummyART->DummyARTTimer1 &&
        Due(timerDummyArt_, fDummyART->DummyARTTimer1->Enabled, fDummyART->DummyARTTimer1->Interval, NowMs()))
    {
        fDummyART->DummyARTTimer1Timer(fDummyART->DummyARTTimer1);
        GPIB_ENGINE_CLOSE_CHECK();
    }

    // P7: page commands (golden: user clicks on the bridge's own form, handled on the form thread)
    {
        const std::vector<std::string> cmds = testercomm::UiChannel::Instance().Take(kUiKey);
        for (size_t i = 0; i < cmds.size(); ++i)
        {
            ApplyUiCommand(cmds[i]);
            GPIB_ENGINE_CLOSE_CHECK();
        }
    }
    {
        const unsigned long long now = NowMs();
        if (now - lastUiMs_ >= kUiPeriodMs)
        {
            lastUiMs_ = now;
            const IGpibDriver* d = GetGpibDriver();
            testercomm::UiChannel::Instance().Publish(kUiKey, BuildUiSnapshot(up_.load(), d ? d->Name() : "none"));
            testercomm::UiChannel::Instance().Publish("gpib.home", BuildHomeFragment(up_.load()));   // AI(W906-TC-SHARED) 20261001 (St02-E): the 首頁 part
        }
    }

#undef GPIB_ENGINE_CLOSE_CHECK
    return kLoopMs;
}

void GpibEngine::Teardown()
{
    up_.store(false);
    // fRS232Main first: its CommTester reader thread queues into SerialPoll.
    delete fRS232Main;
    fRS232Main = 0;
    delete fDummyART;
    fDummyART = 0;
    g_bridgeTok.store(0);
    delete SerialPoll;   // stops CommAMD / CommAMD2
    SerialPoll = 0;
    testercomm::UiChannel::Instance().Publish(kUiKey, "{\"up\":false}");
    g_handlerTok.store(0);
    HMountWnd = 0;
    GHandler2Gpib = 0;
    //AI(W906-GB-ONL) 20261007 (Jerry, J-19): hand the board back BEFORE the driver goes away.  golden has no
    //  equivalent because its bridge is a separate exe -- process exit releases the board.  In-process, skipping
    //  this left gpib0 owned by wb_serve, so the NEXT life's ibfind("gpib0") failed every time (measured 1007:
    //  21 x "Error Open GPIB0", then ProcessAddress() gave up at iErrorCT>10 and stopped logging), i.e. one
    //  Interface switch killed GPIB until wb_serve was restarted.  noncontroller is the global ProcessAddress()
    //  assigned; -1 means ibfind never succeeded, so there is nothing to release.
    if (noncontroller >= 0)
    {
        ibonl(noncontroller, 0);
        noncontroller = -1;
    }
    SetGpibDriver(0);
    delete ownedDriver_;
    ownedDriver_ = 0;
    mailbox_ = 0;
    started_ = false;
    g_live.store(0);
}

bool THandlerTesterSide::StartBridgeProgram()
{
    // golden CreateProcess(d:\gpib9045\H9046_32GPIB.exe / d:\RS232Standard\RS232Standard.exe), and
    // TerminateProcess of the old one when TestIF.iTestType changed (WakeupGPIB).  Which engine serves which type
    // is registered by the composition root (P3): GPIB_MODE -> GpibEngine, RS232_MODE and TTL_MODE -> Rs232Engine.
    if (hub == 0)
        return false;
    const int t = EffectiveBridgeTestType();   //AI(W906-GB-P2d) 20260926: the Off-Line rule (see OffLineGpibWay)
    PublishSettings();                          //AI(W906-GB-P6) 20260926: before the engine starts / restarts (its FormShow reads them)
    if (hub->CurrentTestType() != t || !hub->IsUp())
        W906_GpibAuxBeforeBridgeStart(t);       //AI(W906-GB-P6) 20260926: 2A + Q2(a) -- seeds the recipe once, publishes the framing LoadSetupData reads
    //AI(W906-TC-AUTOOPEN) 20261007 (Jerry, J-18 之二): golden's WakeupGPIB CreateProcess's the bridge exe with no
    //  SW_HIDE (906 main.cpp:17878), so its window APPEARS whenever the bridge is launched -- the operator does not
    //  go looking for it.  The port's equivalent of that window is the testercomm page, and the port showed it
    //  never: the page table row was kPgWeb with an empty form name, so C++ could not ask for it (see
    //  WebPageTable.cpp).  Now it is { "TSerialPoll", kPgBoth } and this is the CreateProcess moment.
    //  ⚠ Only on a real transition.  PageProgramSet bumps wseq every call and each HMI obeys each wseq once, so
    //  signalling on every StartBridgeProgram() would re-pop the window at the caller's tick rate.  golden shows it
    //  when the exe is (re)launched: a type change (old one terminated, new one started) or a bridge that was down.
    const bool typeChanged = (hub->CurrentTestType() != t);
    const bool wasUp       = hub->IsUp();
    bool ok;
    if (typeChanged)
        ok = hub->SelectTestType(t);
    else if (!wasUp)
        ok = hub->Restart();     // it closed itself (golden: the exe exited and is launched again)
    else
        ok = true;
    //  Through W906_FormProgramShow (W906FormShowing.h), NOT W906_PageProgramSet directly: the body of that lives
    //  in WebPageTable.cpp, which only wb_serve links.  Calling it from a LIBRARY breaks every ctest that links
    //  ht9045_testercomm_handler with an undefined reference (measured 1007: test_testercomm_handler,
    //  test_w1_art_brand, test_ela_timedata).  The hook is installed by wb_serve (tools/wb_serve.cpp:4406) and is
    //  0 under ctest ⇒ no-op, which is the same house pattern as uhome.cpp:648.
    if (ok && (typeChanged || !wasUp))
        W906_FormProgramShow("TSerialPoll", true,
                             "HandlerTesterSide.cpp StartBridgeProgram (golden WakeupGPIB CreateProcess, no SW_HIDE)");
    return ok;
}

void THandlerTesterSide::CloseGpibProgram(AnsiString Src)
{
//    if(TestIF.iTestType==RS232_MODE)                                          //wei 20150703 因為測試機不能關閉      //Isaac 20200903 :TTL RS232通訊，Mark
//        return ;

    if(bFind==false)
        return ;

    if(LastSet.iRunStartMode==rsmQAMode && bQAModeFinishCleanOut==true)         //Steven 20141023 : QA做完後的Bin
        return;

    COPYDATASTRUCT *pcp=new COPYDATASTRUCT ;
    pcp->dwData=0;
    HHandler2Gpib.bCloseGpib=true;
    if(CUSTOMER_CODE==CC_MTI || CUSTOMER_CODE==CC_PTI)                          //Sam 20190429 : Add CC_PTI_NEWWORK
        HHandler2Gpib.iLotStatus = 0;                                           //ChungHung OLP 聚成專用

    HHandler2Gpib.iSendCommand=MSG_CMD_CloseGpib;                               //wei 20150408 Add Close GPIB Command   MSG_CMD_NONE-->MSG_CMD_CloseGpib
    pcp->cbData=sizeof(HHandler2Gpib);
    pcp->lpData=(unsigned char *)&HHandler2Gpib.iSendCommand;
    SendToBridge(pcp);                                                          //AI(W906-GB-P2a) 20260926: rule 4, golden SendMessage(HVisionWnd,WM_COPYDATA,(WPARAM) NULL, (LPARAM)pcp);
    delete pcp;
    HHandler2Gpib.bCloseGpib=false;                                             //kevin 20150819 off-line 一直關GPIB
    MyDBIProcess("Process", "GPIB Close - "+Src);
    WakeupGPIBdelay.SetSecAndOn(5);
    bFind=false;
    //AI(W906-TC-AUTOOPEN) 20261007 (Jerry, J-18 之二): the other half of StartBridgeProgram's want=open.  golden
    //  does not TerminateProcess here (see :355) -- it sends MSG_CMD_CloseGpib and the bridge exe closes ITSELF,
    //  so its window goes away.  The port's equivalent of that window is the testercomm page, so tell the HMI.
    //  Port-side addition inside a golden body, same pattern as the other page-table writes; the golden statements
    //  are untouched.  Through W906_FormProgramShow, not W906_PageProgramSet directly -- that body is in
    //  WebPageTable.cpp, which only wb_serve links, so a library-side direct call breaks the ctests that link
    //  ht9045_testercomm_handler (measured 1007).  Hook is 0 under ctest ⇒ no-op, as uhome.cpp:654.
    W906_FormProgramShow("TSerialPoll", false,
                         "HandlerBridgeCtl.cpp CloseGpibProgram (golden: the bridge exe closes itself)");
}

static void TestDriverWrappers()
{
    using namespace gpibbridge;
    SetGpibDriver(0);
    CHECK(ibfind("GPIB0") < 0);
    CHECK((ibsta & ERR) != 0);
    char b[8];
    ibrd(0, b, sizeof(b));
    CHECK((ibsta & ERR) != 0);

    //AI(W906-GB-ONL) 20261007 (Jerry, J-19): with no driver the ibonl wrapper must fail like the others, not crash.
    CHECK((ibonl(0, 0) & ERR) != 0);

    SimGpibDriver sim;
    SetGpibDriver(&sim);
    CHECK(ibfind("GPIB0") == 0);
    CHECK((ibsta & ERR) == 0);
    ibpad(0, 5);
    CHECK(sim.PrimaryAddress() == 5);
    //AI(W906-GB-PADSEEN) 20261007 (Jerry, J-19 "C"): what the CARD took, as opposed to LastSet.GpibAddress (what
    //  the status bar shows).  Those two silently disagreeing is the 1007 fault, so this must follow ibpad exactly.
    CHECK(LastPrimaryAddress() == 5);

    //AI(W906-GB-ONL) 20261007: the release reaches the driver.  -1 = never called, so a regression that drops the
    //  ibonl() out of GpibEngine::Teardown() shows up as -1 in the lifecycle check below.
    CHECK(sim.LastOnline() == -1);
    ibonl(0, 0);
    CHECK(sim.LastOnline() == 0);
    CHECK((ibsta & ERR) == 0);

    ibwait(0, 0);
    CHECK((ibsta & LACS) == 0);
    sim.TesterWrite("FULLSITES?");
    ibwait(0, 0);
    CHECK((ibsta & LACS) != 0);
    char buf[64];
    std::memset(buf, 0, sizeof(buf));
    ibrd(0, buf, sizeof(buf) - 1);
    CHECK(ibcnt == 10);
    CHECK(std::strcmp(buf, "FULLSITES?") == 0);
    CHECK((ibsta & END) != 0);
    ibwait(0, 0);
    CHECK((ibsta & LACS) == 0);

    // not addressed to talk: the write fails like a real device write with no listener
    const char* ans = "Fullsites 00000003";
    ibwrt(0, ans, (long)std::strlen(ans));
    CHECK((ibsta & ERR) != 0);
    CHECK(sim.TakeBridgeWrites().empty());
    sim.SetTalkAddressed(true);
    ibwait(0, 0);
    CHECK((ibsta & TACS) != 0);
    ibwrt(0, ans, (long)std::strlen(ans));
    CHECK((ibsta & ERR) == 0);
    CHECK(ibcnt == (long)std::strlen(ans));
    std::vector<std::string> w = sim.TakeBridgeWrites();
    CHECK(w.size() == 1 && w[0] == ans);

    ibrsv(0, 0x41);
    std::vector<int> srq = sim.TakeSrqBytes();
    CHECK(srq.size() == 1 && srq[0] == 0x41);

    sim.FindFails = true;
    CHECK(ibfind("GPIB0") < 0);
    CHECK((ibsta & ERR) != 0);

    SetGpibDriver(0);
    //AI(W906-GB-PADSEEN) 20261007: a driver swap is a new bridge life -- the next card's address is unknown again.
    CHECK(LastPrimaryAddress() == -1);
    //  ...and an ibpad with no card must not invent one (NoCard() returns before the driver is touched).
    //  NOTE: SimGpibDriver::ibpad() cannot be made to fail -- FindFails only gates ibfind, and ibpad Recompute()s
    //  to CMPL -- so the no-driver path is the one failure this test can actually exercise.
    ibpad(0, 9);
    CHECK((ibsta & ERR) != 0);
    CHECK(LastPrimaryAddress() == -1);
}

static void TestFullLifecycle()
{
    const char* on = std::getenv("HT9045_GPIB_FULL_TEST");
    if (!on || std::strcmp(on, "1") != 0)
    {
        std::printf("full lifecycle: skipped (set HT9045_GPIB_FULL_TEST=1; writes D:\\GPIBLOG like golden)\n");
        return;
    }
    char tmp[MAX_PATH];
    ::GetTempPathA(sizeof(tmp), tmp);
    std::string dir = std::string(tmp) + W906_TestTmpName("ht9045_gpib_ctest");   // AI(W906-ST02-C17) 20261005 (St02-E): per-process scratch name (St01 E-039; tests/w906_test_tmpname.h)
    ::CreateDirectoryA(dir.c_str(), 0);
    const std::string gen = dir + "\\general.ini";
    const std::string hgen = dir + "\\Gerneral.ini";
    WriteText(gen, "[Version]\r\nModel=9045GPIB\r\n");
    // CUSTOMER_CODE 910 (CC_SPIL_SHINCHU) is not in golden RS232.cpp:112-119, so the aux RS232 line defaults to OFF
    // and no real COM port is opened (code 0 = CC_HONPREC_QC would default it ON and open Setup.ini's COM port).
    WriteText(hgen, "[Version]\r\nModel=HT-9045\r\n[System]\r\nCUSTOMER_CODE=910\r\n");
    gpibbridge::GpibEngine::OverrideIniPaths(gen, hgen);   // applied after the per-life ResetBridgeGlobals()

    gpibbridge::SimGpibDriver sim;
    gpibbridge::GpibEngine::InjectDriver(&sim);

    Recorder r;
    r.threadId = ::GetCurrentThreadId();
    testercomm::TesterCommHub hub;
    hub.RegisterFactory(testercomm::kTestTypeGpib, &gpibbridge::GpibEngine::Create);
    hub.SetHandlerSink(&RecordSink, &r);

    OneLife(hub, r, 1);
    //AI(W906-GB-ONL) 20261007 (Jerry, J-19): a finished bridge life must hand the board back.  golden does not
    //  need this (its bridge is its own exe), but in-process the board stayed owned by wb_serve and life 2's
    //  ibfind("gpib0") failed -- measured 1007 on the laptop as 21 x "Error Open GPIB0".  -1 here = Teardown()
    //  never called ibonl; 1 = it put the board back ONLINE, which is not a release.
    CHECK(sim.LastOnline() == 0);
    if (sim.LastOnline() != 0)
        std::printf("  life 1: board not released (LastOnline=%d)\n", sim.LastOnline());
    OneLife(hub, r, 2);
    CHECK(!r.wrongThread);   // every bridge -> Handler packet was served on this (Handler) thread
    CHECK(hub.Thread().EngineErrors() == 0);
    CHECK(hub.HandlerErrors() == 0);         // exceptions out of OnMyCopyMsg
    if (hub.Thread().EngineErrors() != 0)
        std::printf("  TesterComm thread errors: %lu\n", hub.Thread().EngineErrors());

    gpibbridge::GpibEngine::InjectDriver(0);
    gpibbridge::GpibEngine::OverrideIniPaths(std::string(), std::string());
    W906_TestTmpRemoveTree(dir);   // AI(W906-ST02-C17) 20261005 (St02-E): per-process scratch name (St01 E-039; tests/w906_test_tmpname.h): remove this run's scratch folder
}

